-- +goose StatementBegin
INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.122.0',
  '2026-10-23',
  'Пульт ТВ: раздел «Аниме», сворачиваемые разделы и доп материалы сериала',
  E'В медиатеке появился раздел **«Аниме»** — сразу после «Фильмов». Это отдельная библиотека (в конфиге агента вид `anime`), во всём остальном такая же, как сериалы: постеры, «Инфо», поиск в интернете, разбор по качеству.\n\nЛюбой раздел на главной теперь **сворачивается** — стрелкой слева от названия или нажатием на само название. «Музыка» и «Фото» занимают пол-экрана, и листать их мимо каждый раз, чтобы добраться до фильмов, незачем. Что свёрнуто, помнит приставка: на телефоне своё.\n\nУ сериала появились **доп материалы**. Это папка «SPs», «Specials», «Extras», «Бонусы» или «Доп материалы» — внутри сезона (у аниме так лежат коротышки, по одной на серию) или рядом с сезонами (там обычно «как снимался сериал»). Помечать ничего не надо: нашлась папка с таким именем — значит, допы. На экране сериала они всегда видны отдельной кнопкой рядом с сезонами и открываются обычным списком, а в счёт серий не идут: «24 серии · 2 сезона · 24 допа».\n\nКак они попадают в то, что играется само, решают две галочки. «Смотреть вместе со спешиалами» — включена по умолчанию и живёт один сеанс: это про то, подмешивать ли допы в список проигрывания вообще. «Спешлы после каждой серии» — выключена по умолчанию и запоминается у каждого сериала отдельно: выключена — допы идут после всех сезонов, как ещё один сезон; включена — каждый доп встаёт сразу за своей серией. Первое подходит для «как снимался сериал», второе — для аниме, где коротышка привязана к серии.\n\nПервое аниме на приставке — «Kusuriya no Hitorigoto» (два сезона, 48 серий и 48 коротышек).',
  E'Агент: новый вид библиотеки `anime` (`parseRoots`), `isVideoLib` вместо сравнения с "video" в четырёх местах (постеры, «Инфо», админский поиск постера, `CanPoster`), `rawVideoTiles` возвращает третий список, `catalogData.Anime`, в разборе по качеству аниме тоже участвует. Подборки (`collTiles`) по-прежнему раскладываются только по «Фильмам» и «Сериалам».\n\nextras.go: `isExtrasDir` по списку имён (не «всё, что не сезон»: папка с незнакомым именем скорее сезон под чужим названием, и утащить её в допы хуже, чем не узнать); `seriesParts` — сезоны с допами каждого сразу за ним, допы рядом с сезонами в конце; `seasonChain` — порядок для автоперехода; `mixExtras` — пара по порядку при равном числе, иначе по явному номеру (`S01E02`, `1x02`, `E12`, ` - 12 - `): «первое число» ловило бы `1080p` и `x265`. Подмешивает агент в `seasonItems`, которым пользуются и `/api/browse?extras=1`, и `/api/next-season?extras=1`, — иначе список на экране и то, что играется дальше, разошлись бы. `seriesDirOf` поднимается до папки прямо под корнем библиотеки: у допов внутри сезона «папка сезона = папка файла» не работает.\n\nНастройка «после каждой серии» — `extras.json`, ключ ПУТЬ (как в избранном: id это хеш пути, переименование в админке сбросило бы её), `POST /api/extras {id,inline}` без пина, `extras.move` в переименовании. Сеансовая галочка живёт на странице (`sessionStorage htv.extras`) и едет параметром.\n\nСтраница: `secHTML`/`toggleSec` — свёрнутость в `localStorage htv.secclosed`, переключение прямо в DOM (перерисовка увела бы фокус в начало); раздел «Аниме» после «Фильмов», пустым не показывается; `seasonsOf` считает сезоны без допов; `extrasQ()` добавляет `extras=1` в четырёх местах — список сезона, «Смотреть с начала», «Продолжить» и переход к следующему сезону.\n\nsend-series.py: `--anime` и `ANIME_ROOT` (`/mnt/mybook/rudb/media/anime`). Дорожку по-прежнему выбирают при отправке: плеер — `<video>` в браузере, переключателя дорожек у него нет, играет первая, субтитры ASS отбрасываются. У «Аптекарши» шесть русских озвучек — уехала AniLibria (`--audio 2`), у коротышек дорожка одна (`--audio 0`).\n\nСемь новых тестов (`extras_test.go`): раздел аниме, кнопки допов и счёт серий, режим по умолчанию, порядок вперемешку с жизнью после перезапуска, пара по номеру, список имён папок, автопереход при трёх сочетаниях галочек. Проверено вживую: страница в браузере против тестовой библиотеки (сворачивание, обе галочки, список «серия — коротышка — серия») и перенос аниме на res-i3.'
);
-- +goose StatementEnd

